112	    /** Common street-type abbreviations expanded during address normalization. */
113	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
114	        "ST", "STREET",
115	        "RD", "ROAD",
116	        "AVE", "AVENUE");
117	
118	    /** Fixed city-to-region table used to derive an owner's locality. */
119	    private static final Map<String, String> CITY_REGION = Map.of(
120	        "Sydney", "NSW",
121	        "Melbourne", "VIC",
122	        "Brisbane", "QLD");
123	
124	    /** Fixed region-to-postcode-range table (inclusive) used to validate a postcode. */
125	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
126	        "NSW", new int[] {2000, 2099},
127	        "VIC", new int[] {3000, 3099},
128	        "QLD", new int[] {4000, 4099});
129	
130	    /** Fixed region-to-timezone table (IANA names) used to derive an owner's timezone. */
131	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
132	        "NSW", "Australia/Sydney",
133	        "VIC", "Australia/Melbourne",
134	        "QLD", "Australia/Brisbane");
135	
136	    /**
137	     * Return the owner's address. When a structured address is supplied (a non-blank
138	     * {@code addressLine1}) it takes precedence and the value is composed as the
139	     * normalized {@code addressLine1}, with a single space and the normalized
140	     * {@code addressLine2} appended when an {@code addressLine2} is present.
141	     * Otherwise the flat {@code address} is returned, preserving backward
142	     * compatibility for owners supplied in the flat form.
143	     */
144	    public String getAddress() {
145	        if (this.addressLine1 != null && !this.addressLine1.isBlank()) {
146	            if (this.addressLine2 != null && !this.addressLine2.isBlank()) {
147	                return this.addressLine1 + " " + this.addressLine2;
148	            }
149	            return this.addressLine1;
150	        }
151	        return this.address;
152	    }
153	
154	    /**
155	     * Set the owner's flat address, normalizing it to a canonical form so it is both
156	     * stored and returned consistently. Leading/trailing whitespace is trimmed,
157	     * internal runs of whitespace are collapsed to a single space, the value is
158	     * upper-cased, and common street-type abbreviations are expanded ({@code ST ->
159	     * STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value is
160	     * left as-is.
161	     */
162	    public void setAddress(String address) {
163	        this.address = normalizeAddress(address);
164	    }
165	
166	    public String getAddressLine1() {
167	        return this.addressLine1;
168	    }
169	
170	    /**
171	     * Set the first line of the owner's structured address, normalized the same way
172	     * as the flat {@link #setAddress(String)} (trimmed, whitespace collapsed,
173	     * upper-cased, street-type abbreviations expanded). A {@code null} value is left
174	     * as-is.
175	     */
176	    public void setAddressLine1(String addressLine1) {
177	        this.addressLine1 = normalizeAddress(addressLine1);
178	    }
179	
180	    public String getAddressLine2() {
181	        return this.addressLine2;
182	    }
183	
184	    /**
185	     * Set the optional second line of the owner's structured address, normalized the
186	     * same way as {@link #setAddressLine1(String)}. A {@code null} value is left
187	     * as-is.
188	     */
189	    public void setAddressLine2(String addressLine2) {
190	        this.addressLine2 = normalizeAddress(addressLine2);
191	    }
192	
193	    /**
194	     * Normalize an address string to its canonical form: trimmed, whitespace
195	     * collapsed, upper-cased, with common street-type abbreviations expanded.
196	     * Returns {@code null} for a {@code null} input; a value that is blank once
197	     * trimmed normalizes to the empty string.
198	     */
199	    public static String normalizeAddress(String address) {
200	        if (address == null) {
201	            return null;
202	        }
203	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
204	        if (collapsed.isEmpty()) {
205	            return "";
206	        }
207	        String[] tokens = collapsed.split(" ");
208	        StringBuilder sb = new StringBuilder();
209	        for (int i = 0; i < tokens.length; i++) {
210	            if (i > 0) {
211	                sb.append(' ');
212	            }
213	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
214	        }
215	        return sb.toString();
216	    }
217	
218	    public String getCity() {
219	        return this.city;
220	    }
