231	        this.telephone = telephone;
232	    }
233	
234	    /**
235	     * Return the stored E.164 telephone formatted for humans: a {@code '+'} and the
236	     * country code, a space, then the national digits grouped in threes and separated
237	     * by single spaces (for example {@code '+61412345678' -> '+61 412 345 678'}). The
238	     * North American country code ({@code '+1'}) is one digit; other country codes are
239	     * taken as two. Returns {@code null} when the telephone is not set, and returns the
240	     * raw value unchanged when it is not a well-formed E.164 number.
241	     */
242	    public String getTelephoneDisplay() {
243	        if (this.telephone == null || !this.telephone.matches("^\\+[0-9]+$")) {
244	            return this.telephone;
245	        }
246	        String digits = this.telephone.substring(1);
247	        int countryCodeLength = digits.startsWith("1") ? 1 : 2;
248	        if (digits.length() <= countryCodeLength) {
249	            return this.telephone;
250	        }
251	        String countryCode = digits.substring(0, countryCodeLength);
252	        String national = digits.substring(countryCodeLength);
253	        StringBuilder sb = new StringBuilder("+").append(countryCode);
254	        for (int i = 0; i < national.length(); i += 3) {
255	            sb.append(' ').append(national, i, Math.min(i + 3, national.length()));
256	        }
257	        return sb.toString();
258	    }
259	
260	    public String getEmail() {
261	        return this.email;
262	    }
263	
264	    /**
265	     * Set the owner's email address, normalizing it to lower case so it is both
266	     * stored and returned in a canonical form. A {@code null} value is left as-is.
267	     */
268	    public void setEmail(String email) {
269	        this.email = (email == null) ? null : email.toLowerCase(Locale.ROOT);
270	    }
271	
272	    public String getTitle() {
273	        return this.title;
274	    }
275	
276	    public void setTitle(String title) {
277	        this.title = title;
278	    }
279	
280	    /**
281	     * Return the owner's salutation: the title and last name separated by a single
282	     * space (for example {@code 'DR who'}), or just the last name when no title was
283	     * supplied (a {@code null} or blank title).
284	     */
285	    public String getSalutation() {
286	        if (this.title == null || this.title.isBlank()) {
287	            return getLastName();
288	        }
289	        return this.title + " " + getLastName();
290	    }
291	
292	    public LocalDate getRegistrationDate() {
293	        return this.registrationDate;
294	    }
295	
296	    public void setRegistrationDate(LocalDate registrationDate) {
297	        this.registrationDate = registrationDate;
298	    }
299	
300	    public LocalDate getBirthDate() {
301	        return this.birthDate;
302	    }
303	
304	    public void setBirthDate(LocalDate birthDate) {
305	        this.birthDate = birthDate;
306	    }
307	
308	    /**
309	     * Return the owner's age band derived from the birth date, computed against the
310	     * registration date: {@code 'MINOR'} when under 18, {@code 'ADULT'} when 18 to
311	     * 64 inclusive, and {@code 'SENIOR'} when 65 or older. Returns {@code null} when
312	     * either the birth date or the registration date is not set.
313	     */
314	    public String getAgeBand() {
315	        if (this.birthDate == null || this.registrationDate == null) {
316	            return null;
317	        }
318	        int age = Period.between(this.birthDate, this.registrationDate).getYears();
319	        if (age < 18) {
320	            return "MINOR";
321	        }
322	        if (age < 65) {
323	            return "ADULT";
324	        }
325	        return "SENIOR";
326	    }
327	
328	    public String getPostcode() {
329	        return this.postcode;
330	    }
331	
332	    public void setPostcode(String postcode) {
333	        this.postcode = postcode;
334	    }
335	
336	    /**
337	     * Whether this owner's postcode is valid for its city. A {@code null} postcode
338	     * is always valid (postcode is optional). When present, a postcode is valid if
339	     * the city has no known region, or if it is four digits falling within the
340	     * inclusive range for the city's region ({@code Sydney -> NSW 2000-2099},
341	     * {@code Melbourne -> VIC 3000-3099}, {@code Brisbane -> QLD 4000-4099}).
342	     */
343	    public boolean isPostcodeValidForCity() {
344	        if (this.postcode == null) {
345	            return true;
346	        }
347	        String region = CITY_REGION.get(this.city);
348	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
349	        if (range == null) {
350	            return true;
351	        }
352	        if (!this.postcode.matches("^[0-9]{4}$")) {
353	            return false;
354	        }
355	        int value = Integer.parseInt(this.postcode);
356	        return value >= range[0] && value <= range[1];
357	    }
358	
359	    public String getCustomerCode() {
360	        return this.customerCode;
361	    }
362	
363	    public void setCustomerCode(String customerCode) {
364	        this.customerCode = customerCode;
365	    }
366	
367	    /**
368	     * Return a single Luhn check digit (0-9) computed over the digits contained in
369	     * the owner's customer code, or {@code null} when the customer code is not set.
370	     * Non-digit characters in the code are ignored; the rightmost digit is doubled
371	     * first, following the standard Luhn algorithm.
372	     */
373	    public Integer getCheckDigit() {
374	        if (this.customerCode == null) {
375	            return null;
376	        }
377	        int sum = 0;
378	        boolean doubleDigit = true;
379	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
380	            char c = this.customerCode.charAt(i);
381	            if (c < '0' || c > '9') {
382	                continue;
383	            }
384	            int digit = c - '0';
385	            if (doubleDigit) {
386	                digit *= 2;
387	                if (digit > 9) {
388	                    digit -= 9;
389	                }
390	            }
391	            sum += digit;
392	            doubleDigit = !doubleDigit;
393	        }
394	        return (10 - (sum % 10)) % 10;
395	    }
396	
397	    /**
398	     * Return the owner's fiscal year, formatted {@code 'FY<YY>'} where {@code YY}
399	     * is the last two digits of the fiscal year derived from the (business-day
400	     * adjusted) registration date. The fiscal year starts on 1 July and is named
401	     * after the calendar year in which it ends, so a registration date on or after
402	     * 1 July belongs to the fiscal year ending the following calendar year (for
403	     * example {@code 2026-08-14 -> 'FY27'}), while a date before 1 July belongs to
404	     * the fiscal year ending in that same calendar year. Returns {@code null} when
405	     * the registration date is not set.
406	     */
407	    public String getFiscalYear() {
408	        Integer fiscalYear = fiscalYearOf(this.registrationDate);
409	        if (fiscalYear == null) {
410	            return null;
411	        }
412	        return String.format("FY%02d", fiscalYear % 100);
413	    }
414	
415	    /**
416	     * Return the fiscal year (the calendar year in which the fiscal year ends) that
417	     * the given date falls in, where the fiscal year starts on 1 July, or
418	     * {@code null} when the date is {@code null}.
419	     */
420	    private static Integer fiscalYearOf(LocalDate date) {
421	        if (date == null) {
422	            return null;
423	        }
424	        return date.getMonthValue() >= 7 ? date.getYear() + 1 : date.getYear();
425	    }
426	
427	    /**
428	     * Return the owner's membership number, formatted {@code '<customerCode>-M<YY>'}
429	     * where {@code YY} is the last two digits of the fiscal year derived from the
430	     * registration date (for example {@code 'SMI-0007-M27'}). Returns {@code null}
431	     * when either the customer code or the registration date is not set.
432	     */
433	    public String getMembershipNumber() {
434	        Integer fiscalYear = fiscalYearOf(this.registrationDate);
435	        if (this.customerCode == null || fiscalYear == null) {
436	            return null;
437	        }
438	        return String.format("%s-M%02d", this.customerCode, fiscalYear % 100);
439	    }
440	
441	    public String getHouseholdId() {
442	        return this.householdId;
443	    }
444	
445	    public void setHouseholdId(String householdId) {
446	        this.householdId = householdId;
447	    }
448	
449	    public Integer getNamesakeCount() {
450	        return this.namesakeCount;
451	    }
452	
453	    /**
454	     * Return the owner's membership points, the raw score from which the
455	     * membership level is derived. Starting at {@code 0}, add {@code 2} when an
456	     * email address is present, {@code 1} when the owner has no namesakes
457	     * (namesake count is {@code 0}), {@code 2} for a household of {@code 3} or
458	     * more, and {@code 3} when the owner's tenure (the number of fiscal years
459	     * elapsed since the registration date, the fiscal year starting on 1 July) is
460	     * at least {@code 1}.
461	     */
462	    public Integer getMembershipPoints() {
463	        int points = 0;
464	        boolean hasEmail = this.email != null && !this.email.isBlank();
465	        if (hasEmail) {
466	            points += 2;
467	        }
468	        if (this.namesakeCount != null && this.namesakeCount == 0) {
469	            points += 1;
470	        }
471	        if (this.householdSize != null && this.householdSize >= 3) {
472	            points += 2;
473	        }
474	        Integer registrationFiscalYear = fiscalYearOf(this.registrationDate);
475	        if (registrationFiscalYear != null) {
476	            int elapsedFiscalYears = fiscalYearOf(LocalDate.now()) - registrationFiscalYear;
477	            if (elapsedFiscalYears >= 1) {
478	                points += 3;
479	            }
480	        }
481	        return points;
482	    }
483	
484	    /**
485	     * Return the owner's membership level, a number from {@code 1} to {@code 4},
486	     * derived from {@link #getMembershipPoints()}: {@code 1} for {@code 0-1}
487	     * points, {@code 2} for {@code 2-3}, {@code 3} for {@code 4-5}, and
488	     * {@code 4} for {@code 6} or more. When a {@code membershipLevelCap} is set,
489	     * the derived level is capped at it (a level higher than the cap is lowered to
490	     * the cap); the cap records one above the maximum level among the owner's
491	     * household members at creation time.
492	     */
493	    public Integer getMembershipLevel() {
494	        int points = getMembershipPoints();
495	        int level;
496	        if (points >= 6) {
497	            level = 4;
498	        }
499	        else if (points >= 4) {
500	            level = 3;
501	        }
502	        else if (points >= 2) {
503	            level = 2;
504	        }
505	        else {
506	            level = 1;
507	        }
508	        if (this.membershipLevelCap != null && level > this.membershipLevelCap) {
509	            return this.membershipLevelCap;
510	        }
511	        return level;
512	    }
513	
