656	    /**
657	     * Return the owner's derived identity key, which consolidates all duplicate
658	     * detection into a single value: the SHA-256 digest, rendered as 64 lower-case
659	     * hex characters, of {@code '<normalizedTelephone>|<lowerEmail>|<soundex(lastName)>'}.
660	     * The telephone and email are already stored in their normalized (E.164 /
661	     * lower-cased) forms; a missing email contributes an empty segment and the last
662	     * name is reduced to its Soundex code. A create is rejected only when a new
663	     * owner's whole identity key equals an existing owner's.
664	     */
665	    public String getIdentityKey() {
666	        String telephonePart = this.telephone == null ? "" : this.telephone;
667	        String emailPart = (this.email == null) ? "" : this.email.toLowerCase(Locale.ROOT);
668	        String soundexPart = soundex(getLastName());
669	        String key = telephonePart + "|" + emailPart + "|" + soundexPart;
670	        try {
671	            byte[] digest = MessageDigest.getInstance("SHA-256")
672	                .digest(key.getBytes(StandardCharsets.UTF_8));
673	            StringBuilder sb = new StringBuilder(digest.length * 2);
674	            for (byte b : digest) {
675	                sb.append(String.format("%02x", b));
676	            }
677	            return sb.toString();
678	        }
679	        catch (NoSuchAlgorithmException e) {
680	            throw new IllegalStateException(e);
681	        }
682	    }
683	
684	    /**
685	     * Compute the American Soundex code of the given name: its first letter followed
686	     * by three digits derived from the remaining consonants (vowels act as separators,
687	     * {@code H} and {@code W} are transparent, and adjacent equal codes collapse),
688	     * zero-padded and truncated to four characters. Returns an empty string when the
689	     * name is {@code null} or holds no letters.
690	     */
691	    public static String soundex(String name) {
692	        if (name == null) {
693	            return "";
694	        }
695	        StringBuilder letters = new StringBuilder();
696	        for (int i = 0; i < name.length(); i++) {
697	            char c = name.charAt(i);
698	            if (Character.isLetter(c)) {
699	                letters.append(Character.toUpperCase(c));
700	            }
701	        }
702	        if (letters.length() == 0) {
703	            return "";
704	        }
705	        StringBuilder code = new StringBuilder();
706	        code.append(letters.charAt(0));
707	        char prevDigit = soundexDigit(letters.charAt(0));
708	        for (int i = 1; i < letters.length() && code.length() < 4; i++) {
709	            char c = letters.charAt(i);
710	            if (c == 'H' || c == 'W') {
711	                continue;
712	            }
713	            char digit = soundexDigit(c);
714	            if (digit != '0' && digit != prevDigit) {
715	                code.append(digit);
716	            }
717	            prevDigit = digit;
718	        }
719	        while (code.length() < 4) {
720	            code.append('0');
721	        }
722	        return code.toString();
723	    }
724	
725	    private static char soundexDigit(char c) {
726	        switch (c) {
727	            case 'B': case 'F': case 'P': case 'V':
728	                return '1';
729	            case 'C': case 'G': case 'J': case 'K': case 'Q': case 'S': case 'X': case 'Z':
730	                return '2';
731	            case 'D': case 'T':
732	                return '3';
733	            case 'L':
734	                return '4';
735	            case 'M': case 'N':
736	                return '5';
737	            case 'R':
738	                return '6';
739	            default:
740	                return '0';
741	        }
742	    }
